    [return: DimensionOf(nameof(value), Root = 2)]
    public static UnknownUnit Sqrt(this LinearPowerDensity value) => new(Math.Sqrt(value.SI));

    public static LinearPowerDensity Sum(this IEnumerable<LinearPowerDensity> values)
    {
        double sum = 0;
        foreach (var v in values) sum += v.SI;
        return LinearPowerDensity.FromSI(sum);
    }

    public static LinearPowerDensity Average(this IEnumerable<LinearPowerDensity> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : LinearPowerDensity.FromSI(sum / count);
    }

    public static LinearPowerDensity Min(this IEnumerable<LinearPowerDensity> values) => Aggregate(values, Math.Min);
    public static LinearPowerDensity Max(this IEnumerable<LinearPowerDensity> values) => Aggregate(values, Math.Max);

    private static LinearPowerDensity Aggregate(IEnumerable<LinearPowerDensity> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return LinearPowerDensity.FromSI(result);
    }
}
